corrected_code:
const express = require('express');
const { authenticator } = require('otplib');
const { WireTransfer } = require('../models/transfers');

const app = express();
app.use(express.json());

app.post('/api/transfers/:transferId/authorize-mfa', async (req, res) => {
  if (!req.user || !req.user.id || !req.user.mfaSecret) {
    return res.status(401).json({ error: 'Authenticated user with configured MFA required' });
  }

  const { totpToken } = req.body;
  const { transferId } = req.params;

  if (!totpToken) {
    return res.status(400).json({ error: 'TOTP step-up token required' });
  }

  // Ensure transfer exists and belongs to the authenticated user
  const transfer = await WireTransfer.findOne({
    where: {
      id: transferId,
      initiatorUserId: req.user.id
    }
  });

  if (!transfer) {
    return res.status(403).json({ error: 'Access denied: transfer not found or owned by another user' });
  }

  const isMfaValid = authenticator.verify({
    token: totpToken,
    secret: req.user.mfaSecret
  });

  if (!isMfaValid) {
    return res.status(401).json({ error: 'Invalid MFA step-up code' });
  }

  transfer.status = 'APPROVED_AND_RELEASED';
  transfer.authorizedAt = new Date();
  await transfer.save();

  res.json({ message: 'Wire transfer authorized and released', transferId });
});

app.listen(6004);
